UPDATE search_config
SET config_json = JSON_REMOVE(
        config_json,
        REPLACE(
                JSON_UNQUOTE(JSON_SEARCH(config_json, 'one', #{dbIndex}, NULL, '$.database_name[*].key')),
                '.key',
                ''
        )
                  )
WHERE JSON_SEARCH(config_json, 'one', #{dbIndex}, NULL, '$.database_name[*].key') IS NOT NULL;

UPDATE search_config
SET config_json = JSON_SET(
        config_json,
        '$.need_trace_source',
        ${needTrace}
                  )
WHERE status = 1
  AND JSON_UNQUOTE(JSON_EXTRACT(config_json, '$.model_name')) = #{modelName};

UPDATE search_config
SET config_json = JSON_SET(
        config_json,
        '$.thinking', ${thinking}
                  )
WHERE status = 1
  AND JSON_UNQUOTE(JSON_EXTRACT(config_json, '$.model_name')) = #{modelName};

UPDATE search_config
create_by=#{userName},modify_by=#{userName}
,config_json = JSON_SET(config_json, '$.knowledge_base_name_source', '','$.knowledge_base_name','')
id IN
#{id}
AND JSON_EXTRACT(config_json, '$.knowledge_base_name_source') IS NOT NULL AND JSON_EXTRACT(config_json, '$.knowledge_base_name') IS NOT NULL
